export function getCategories() {
  return categories.map(cat => ({
    ...cat,
    count: recipes.filter(r => r.categoryDir === cat.id).length,
  }));
}

export function getFeaturedRecipes() {
  return recipes.filter(r => r.categoryDir === '炒菜' && r.steps && r.steps.length > 0).slice(0, 8);
}

export function getRecipesByCategory(categoryDir) {
  return recipes.filter(r => r.categoryDir === categoryDir);
}

export function getRecipeById(id) {
  return recipes.find(r => r.id === id || r.slug === decodeURIComponent(id) || r.title === decodeURIComponent(id));
}

export function searchRecipes(query) {
  const q = query.toLowerCase();
  return recipes.filter(r =>
    r.title.toLowerCase().includes(q) ||
    (r.flavorType && r.flavorType.toLowerCase().includes(q)) ||
    (r.cookingMethod && r.cookingMethod.toLowerCase().includes(q)) ||
    r.ingredients.some(i => i.toLowerCase().includes(q))
  );
}

export function getFlavorTypes() {
  const map = {};
  for (const r of recipes) {
    if (r.flavorType && r.flavorType !== '/') {
      map[r.flavorType] = (map[r.flavorType] || 0) + 1;
    }
  }
  return Object.entries(map)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count);
}

export function getCookingMethods() {
  const map = {};
  for (const r of recipes) {
    if (r.cookingMethod && r.cookingMethod !== '/') {
      map[r.cookingMethod] = (map[r.cookingMethod] || 0) + 1;
    }
  }
  return Object.entries(map)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count);
}

export function getProcessingLevels() {
  const map = {};
  for (const r of recipes) {
    if (r.processingLevel && r.processingLevel !== '/') {
      map[r.processingLevel] = (map[r.processingLevel] || 0) + 1;
    }
  }
  return Object.entries(map)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count);
}

export function getRandomRecipe() {
  const idx = Math.floor(Math.random() * recipes.length);
  return recipes[idx];
}

export function filterRecipes({ category, flavorType, cookingMethod, processingLevel, query }) {
  let result = recipes;
  if (category && category !== 'all') {
    result = result.filter(r => r.categoryDir === category);
  }
  if (flavorType) {
    result = result.filter(r => r.flavorType === flavorType);
  }
  if (cookingMethod) {
    result = result.filter(r => r.cookingMethod === cookingMethod);
  }
  if (processingLevel) {
    result = result.filter(r => r.processingLevel === processingLevel);
  }
  if (query) {
    const q = query.toLowerCase();
    result = result.filter(r =>
      r.title.toLowerCase().includes(q) ||
      (r.flavorType && r.flavorType.toLowerCase().includes(q)) ||
      (r.cookingMethod && r.cookingMethod.toLowerCase().includes(q)) ||
      r.ingredients.some(i => i.toLowerCase().includes(q))
    );
  }
  return result;
}